def simulateQueue(ops):
    in_stk, out_stk = [], []
    res = []
    def transfer():
        if not out_stk:
            while in_stk: out_stk.append(in_stk.pop())
    for op in ops:
        cmd = op[0]
        if cmd == 'push':
            in_stk.append(op[1])
            res.append(None)
        elif cmd == 'pop':
            transfer()
            res.append(out_stk.pop())
        elif cmd == 'peek':
            transfer()
            res.append(out_stk[-1])
        elif cmd == 'empty':
            res.append(len(in_stk) == 0 and len(out_stk) == 0)
    return res

