import java.util.*;
public class Solution {
    public List<Object> simulateQueue(List<List<Object>> ops) {
        Stack<Integer> inStk = new Stack<>(), outStk = new Stack<>();
        List<Object> res = new ArrayList<>();
        for (List<Object> op : ops) {
            String cmd = (String) op.get(0);
            if ("push".equals(cmd)) {
                inStk.push(((Number) op.get(1)).intValue());
                res.add(null);
            } else if ("pop".equals(cmd)) {
                if (outStk.isEmpty()) while (!inStk.isEmpty()) outStk.push(inStk.pop());
                res.add(outStk.pop());
            } else if ("peek".equals(cmd)) {
                if (outStk.isEmpty()) while (!inStk.isEmpty()) outStk.push(inStk.pop());
                res.add(outStk.peek());
            } else if ("empty".equals(cmd)) {
                res.add(inStk.isEmpty() && outStk.isEmpty());
            }
        }
        return res;
    }
}
